"use strict";(self.webpackChunkgrc=self.webpackChunkgrc||[]).push([[89036],{61379:e=>{e.exports=JSON.parse('[{"title":"Rich I/O-centric Derived Quantity Operators for Advanced In Situ Processing","authors":["H. Xu","J. Cernuda","A. Kougkas","X.-H. Sun","A. Gainaru","S. Klasky","M. Taufer","N. Tan","K. Assogba","M. Rafique","B. Nicolae","J. Teves","C. Brinker","L. Pouchard","J. Lofstead"],"venue":"The 22nd IEEE International Conference on eScience (eScience\'26)","type":"Conference","date":"August, 2026","month":8,"year":2026,"tags":["IOWarp","Coeus"],"links":{},"slug":"xu-2026-rich-i-o-centric-derived-quantity-8c30","abstract":"Scientific simulations produce increasingly large datasets that surpass practical limits for frequent input and output operations. Although performing analysis directly as data is produced (in situ) can mitigate this problem, embedding such analysis routines into complex scientific codes is often impractical or inflexible.\\nWe address this by introducing derived quantity operators that provide a modular and pluggable framework within high-level I/O libraries, enabling sophisticated in situ analysis to be performed transparently during data output with minimal modifications to the host application. The operators bind to persistent hierarchical storage through operator-declared metadata, allowing cross-timestep and cross-run analysis to be carried out seamlessly within the I/O path.\\n\\nWe demonstrate the capabilities of our operators by integrating correctness validation and important scientific metrics, traditionally executed after simulation runs, directly into the I/O pathway as derived quantities. Our implementation illustrates how complex, non-mathematical analyses such as runtime validation can be efficiently performed during simulation, enabling early detection of errors.\\nOur work broadens the range of in situ analyses achievable through derived quantity operators, promoting more flexible, intelligent, and reliable scientific workflows."},{"title":"Trigger, Render, Reason: Multimodal LLM Agents for Science-Aware Scientific Simulation Monitoring","authors":["H. Xu","J. Cernuda","A. Gainaru","S. Klasky","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'26)","type":"Conference","date":"July, 2026","month":7,"year":2026,"tags":["Coeus","Iowarp"],"links":{},"slug":"xu-2026-trigger-render-reason-multimodal-llm-agents-c360","abstract":"Scientific simulations on leadership-class HPC systems\\nroutinely waste millions of core-hours producing invalid results,\\nyet no tool monitors whether a running simulation computes valid\\nscience. We call this blind spot dark waste: simulations that run to\\ncompletion while computing the wrong answer. We present Vigil,\\nwhich couples deterministic science-aware triggers with multimodal\\nLLM confirmation through a trigger-render-reason pipeline. Vigil\\ninstruments simulations with lightweight checks on derived-quantity\\noperators and regions of interest; when a check detects a potential\\nanomaly, the flagged data is rendered and analyzed by a multimodal\\nmodel to assess scientific validity. Upon confirming invalid behavior,\\nVigil can terminate or restart the simulation from a checkpoint,\\npreventing further expenditure on dark waste. We evaluate Vigil\\nacross four codes spanning numerical instability, pattern dynamics,\\nturbulence dissipation, and molecular-dynamics failures. Vigil detects\\nevery deliberately configured failure with zero false positives and\\nsupplies an actionable semantic verdict for each alert."},{"authors":["H. Xu","A. Kougkas","X.-H. Sun"],"date":"June, 2025","links":{"bibtex":"http://cs.iit.edu/~scs/assets/files/xu-2025-rich-operators.bib","citation":"http://cs.iit.edu/~scs/assets/files/xu-2025-rich-operators.txt","poster":"http://cs.iit.edu/~scs/assets/files/xu-2025-rich-operators.pdf"},"month":6,"slug":"xu-2025-rich-operators-a3f2","tags":["HPC","metadata management","storage"],"title":"Rich Operators for Advanced In Situ Processing","type":"Poster","venue":"The 37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","year":2025}]')}}]);